user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log warn;
pid /var/run/nginx.pid;

events {
  worker_connections 1024;
  use epoll;
}

http {
  include /etc/nginx/mime.types;
  default_type application/octet-stream;

  # 로깅 포맷
  log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                  '$status $body_bytes_sent "$http_referer" '
                  '"$http_user_agent" "$http_x_forwarded_for"';

  access_log /var/log/nginx/access.log main;

  # 성능 최적화
  sendfile on;
  tcp_nopush on;
  tcp_nodelay on;
  keepalive_timeout 65;
  types_hash_max_size 2048;
  client_max_body_size 20M;

  # Gzip 압축
  gzip on;
  gzip_vary on;
  gzip_proxied any;
  gzip_comp_level 6;
  gzip_types text/plain text/css text/xml text/javascript application/json application/javascript application/xml+rss application/rss+xml application/atom+xml image/svg+xml;

  # ============================================================================
  # Upstream 서버 정의 (API 백엔드)
  # ============================================================================
  upstream freelang_backend {
    least_conn;
    server freelang-hybrid-api:3001 max_fails=3 fail_timeout=30s;
  }

  # ============================================================================
  # HTTP → HTTPS 리다이렉트
  # ============================================================================
  server {
    listen 80;
    server_name 253.dclub.kr;
    return 301 https://$server_name$request_uri;
  }

  # ============================================================================
  # HTTPS 서버 (메인)
  # ============================================================================
  server {
    listen 443 ssl http2;
    server_name 253.dclub.kr;

    # SSL 인증서 설정
    ssl_certificate /etc/letsencrypt/live/253.dclub.kr/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/253.dclub.kr/privkey.pem;

    # SSL 보안 설정
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    ssl_prefer_server_ciphers on;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 10m;

    # HSTS (Strict-Transport-Security)
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;

    # 보안 헤더
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-XSS-Protection "1; mode=block" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    # ========== 정적 파일 (캐시) ==========
    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$ {
      proxy_pass http://freelang_backend;
      proxy_cache_valid 30d;
      proxy_cache_key "$scheme$request_method$host$request_uri";
      add_header Cache-Control "public, max-age=2592000, immutable";
      add_header X-Cache-Status $upstream_cache_status;
    }

    # ========== API 엔드포인트 ==========
    location /api/ {
      proxy_pass http://freelang_backend;
      proxy_http_version 1.1;
      proxy_set_header Upgrade $http_upgrade;
      proxy_set_header Connection "upgrade";
      proxy_set_header Host $host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
      proxy_set_header X-Forwarded-Host $host;
      proxy_set_header X-Forwarded-Port $server_port;
      proxy_connect_timeout 60s;
      proxy_send_timeout 60s;
      proxy_read_timeout 60s;
    }

    # ========== WebSocket (GraphQL Subscriptions) ==========
    location /graphql {
      proxy_pass http://freelang_backend;
      proxy_http_version 1.1;
      proxy_set_header Upgrade $http_upgrade;
      proxy_set_header Connection "Upgrade";
      proxy_set_header Host $host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
    }

    # ========== 헬스 체크 ==========
    location /health {
      access_log off;
      proxy_pass http://freelang_backend;
      proxy_http_version 1.1;
      proxy_set_header Connection "";
    }

    # ========== 모니터링 ==========
    location /metrics {
      proxy_pass http://freelang_backend;
      proxy_http_version 1.1;
      access_log off;
    }

    # ========== Prometheus UI ==========
    location /prometheus/ {
      proxy_pass http://freelang-hybrid-prometheus:9090/;
      proxy_set_header Host $host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto https;
    }

    # ========== Grafana UI ==========
    location /grafana/ {
      proxy_pass http://freelang-hybrid-grafana:3000/;
      proxy_set_header Host $host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto https;
    }

    # ========== 기본 경로 ==========
    location / {
      proxy_pass http://freelang_backend;
      proxy_http_version 1.1;
      proxy_set_header Host $host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
      proxy_set_header X-Forwarded-Proto $scheme;
    }
  }
}

